import{_ as r,o,c as n,a3 as s}from"./chunks/framework.D8u9WiMi.js";const l=JSON.parse('{"title":"个人护肤","description":"","frontmatter":{},"headers":[],"relativePath":"other/skin/index.md","filePath":"other/skin/index.md"}'),g={name:"other/skin/index.md"};function d(a,t,e,h,P,i){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="个人护肤" tabindex="-1">个人护肤 <a class="header-anchor" href="#个人护肤" aria-label="Permalink to &quot;个人护肤&quot;">​</a></h1><h2 id="当前产品" tabindex="-1">当前产品 <a class="header-anchor" href="#当前产品" aria-label="Permalink to &quot;当前产品&quot;">​</a></h2><ul><li>适乐肤 (CeraVe) 10% 纯维C精华</li><li>理肤泉 (La Roche-Posay)绿标防晒</li><li>适乐肤 (CeraVe) A醇精华 (蓝瓶)</li><li>适乐肤 (CeraVe) PM乳</li><li>上水和肌水杨酸2%</li></ul><h2 id="使用细节" tabindex="-1">使用细节 <a class="header-anchor" href="#使用细节" aria-label="Permalink to &quot;使用细节&quot;">​</a></h2><h3 id="第一阶段-新手耐受期-第-1-4-周" tabindex="-1">第一阶段：新手耐受期（第 1 - 4 周） <a class="header-anchor" href="#第一阶段-新手耐受期-第-1-4-周" aria-label="Permalink to &quot;第一阶段：新手耐受期（第 1 - 4 周）&quot;">​</a></h3><p><strong>核心目标：</strong> 让皮 肤认识维C、A醇和水杨酸。<strong>严防红肿、脱皮。</strong></p><table tabindex="0"><thead><tr><th><strong>星期</strong></th><th><strong>晨间流程 (防御)</strong></th><th><strong>晚间流程 (适应)</strong></th><th><strong>重点细节</strong></th></tr></thead><tbody><tr><td><strong>周一</strong></td><td>洁面 + <strong>PM乳</strong> + 绿标防晒</td><td>洁面 + <strong>PM乳</strong> + <strong>A醇</strong></td><td><strong>乳液打底</strong>：降低 A醇渗透压</td></tr><tr><td><strong>周二</strong></td><td>洁面 + <strong>PM乳</strong> + 绿标防晒</td><td>洁面 + <strong>PM乳 (厚涂)</strong></td><td><strong>纯修护</strong>：不加任何精华</td></tr><tr><td><strong>周三</strong></td><td>洁面 + <strong>维C(2滴)</strong> + <strong>PM乳</strong></td><td>洁面 + <strong>PM乳</strong> + <strong>A醇</strong></td><td>维C少量试探，避开伤口</td></tr><tr><td><strong>周四</strong></td><td>洁面 + <strong>PM乳</strong> + 绿标防晒</td><td>洁面 + <strong>PM乳 (厚涂)</strong></td><td>停药日，观察是否起皮</td></tr><tr><td><strong>周五</strong></td><td>洁面 + <strong>维C(2滴)</strong> + <strong>PM乳</strong></td><td>洁面 + <strong>水杨酸(仅点涂鼻翼)</strong></td><td>水杨酸只针对黑头，不全脸</td></tr><tr><td><strong>周六</strong></td><td>洁面 + <strong>PM乳</strong> + 绿标防晒</td><td>洁面 + <strong>PM乳</strong> + <strong>A醇</strong></td><td>尝试一周内第 3 次 A醇</td></tr><tr><td><strong>周日</strong></td><td>清水洗脸 + <strong>PM乳</strong></td><td>洁面 + <strong>PM乳 (全脸厚涂)</strong></td><td>给皮肤自我修复的时间</td></tr></tbody></table><h3 id="第二阶段-高效发力期-第-2-4-个月" tabindex="-1">第二阶段：高效发力期（第 2 - 4 个月） <a class="header-anchor" href="#第二阶段-高效发力期-第-2-4-个月" aria-label="Permalink to &quot;第二阶段：高效发力期（第 2 - 4 个月）&quot;">​</a></h3><p><strong>核心目标：</strong> <strong>淡化印子、平滑肤质。</strong> 此时皮肤已耐受，可以让功效成分直接接触皮肤。</p><table tabindex="0"><thead><tr><th><strong>星期</strong></th><th><strong>晨间流程 (亮肤)</strong></th><th><strong>晚间流程 (代谢)</strong></th><th><strong>重点细节</strong></th></tr></thead><tbody><tr><td><strong>周一</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳</strong></td><td>A醇直接上脸，改善痘坑</td></tr><tr><td><strong>周二</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>水杨酸(局部)</strong> + <strong>PM乳</strong></td><td>重点清理T区和闭口</td></tr><tr><td><strong>周三</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳</strong></td><td>坚持抗氧，预防印子变黑</td></tr><tr><td><strong>周四</strong></td><td>洁面 + <strong>PM乳</strong> + 绿标防晒</td><td>洁面 + <strong>PM乳 (加量)</strong></td><td><strong>必须保留</strong>的停药缓冲日</td></tr><tr><td><strong>周五</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳</strong></td><td>保持高频代谢，细化肤质</td></tr><tr><td><strong>周六</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>水杨酸(全脸/局部)</strong></td><td>一周一次深度清理角质</td></tr><tr><td><strong>周日</strong></td><td>清水洗脸 + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>PM乳 (厚敷)</strong></td><td>缓解一周积累的干燥感</td></tr></tbody></table><h3 id="第三阶段-高阶维持期-第-5-个月以后" tabindex="-1">第三阶段：高阶维持期（第 5 个月以后） <a class="header-anchor" href="#第三阶段-高阶维持期-第-5-个月以后" aria-label="Permalink to &quot;第三阶段：高阶维持期（第 5 个月以后）&quot;">​</a></h3><p><strong>核心目标：</strong> <strong>极致细腻、改善痘坑边缘。</strong> 适合已经成为“城墙皮”的你。</p><table tabindex="0"><thead><tr><th><strong>星期</strong></th><th><strong>晨间流程 (极致抗氧)</strong></th><th><strong>晚间流程 (深度磨皮)</strong></th><th><strong>重点细节</strong></th></tr></thead><tbody><tr><td><strong>周一</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳</strong></td><td>持续刺激胶原蛋白</td></tr><tr><td><strong>周二</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳</strong></td><td><strong>连用两晚</strong>：强化代谢</td></tr><tr><td><strong>周三</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>水杨酸(全脸)</strong> + <strong>PM乳</strong></td><td>全脸抛光，告别暗沉</td></tr><tr><td><strong>周四</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳</strong></td><td>A醇频率提升至 4 次/周</td></tr><tr><td><strong>周五</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳</strong></td><td>追求皮肤的“透亮感”</td></tr><tr><td><strong>周六</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳</strong> + 防晒</td><td>洁面 + <strong>水杨酸(全脸)</strong> + <strong>PM乳</strong></td><td>强力磨平角质不平整</td></tr><tr><td><strong>周日</strong></td><td>清水洗脸 + <strong>PM乳</strong></td><td>洁面 + <strong>PM乳 (极厚涂)</strong></td><td><strong>高强度后必须彻底修复</strong></td></tr></tbody></table><table tabindex="0"><thead><tr><th><strong>星期</strong></th><th><strong>晨间流程 (防御+亮肤)</strong></th><th><strong>晚间流程 (代谢+修护)</strong></th><th><strong>护肤重点</strong></th></tr></thead><tbody><tr><td><strong>周一</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳(薄)</strong> + 绿标防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳(厚)</strong></td><td>开启一周胶原蛋白再生</td></tr><tr><td><strong>周二</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳(薄)</strong> + 绿标防晒</td><td>洁面 + <strong>水杨酸(局部)</strong> + <strong>PM乳</strong></td><td>清理黑头、闭口，控油</td></tr><tr><td><strong>周三</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳(薄)</strong> + 绿标防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳(厚)</strong></td><td>针对痘坑边缘进行“磨边”</td></tr><tr><td><strong>周四</strong></td><td>洁面 + <strong>PM乳</strong> + 绿标防晒 (停VC)</td><td>洁面 + <strong>霏丝佳</strong> (停所有功效精华)</td><td><strong>皮肤喘息日</strong>，深度强韧屏障</td></tr><tr><td><strong>周五</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳(薄)</strong> + 绿标防晒</td><td>洁面 + <strong>A醇</strong> + <strong>PM乳(厚)</strong></td><td>强化抗氧与紧致效果</td></tr><tr><td><strong>周六</strong></td><td>洁面 + <strong>维C</strong> + <strong>PM乳(薄)</strong> + 绿标防晒</td><td>洁面 + <strong>水杨酸(全脸/局部)</strong> + <strong>PM乳</strong></td><td>深度大扫除，细致毛孔</td></tr><tr><td><strong>周日</strong></td><td>清水洗脸 + <strong>PM乳</strong> (+ 绿标防晒)</td><td>洁面 + <strong>PM乳</strong> + <strong>理肤泉B5(点涂印子)</strong></td><td>集中淡化红印，准备下一周</td></tr></tbody></table>',14)])])}const b=r(g,[["render",d]]);export{l as __pageData,b as default};
